#!/usr/bin/env python3
"""RedCap Loom 角色化工程工作流检查器。"""

from __future__ import annotations

import argparse
import json
import pathlib
import sys
from typing import Any

REPO_ROOT = pathlib.Path(__file__).resolve().parents[2]
DEFAULT_CONTRACT = REPO_ROOT / "assets" / "contracts" / "loom-workflow.json"
REQUIRED_ROLES = {
    "product_manager",
    "architect",
    "developer",
    "tester",
    "reviewer",
    "cap_orchestrator",
}
REQUIRED_PHASES = {
    "idea_intake",
    "architecture_design",
    "implementation",
    "quality_assurance",
    "review_and_acceptance",
    "change_intake",
    "closeout",
    "blocked",
}
REQUIRED_LINEAR_TRANSITIONS = {
    ("idea_intake", "architecture_design"),
    ("architecture_design", "implementation"),
    ("implementation", "quality_assurance"),
    ("quality_assurance", "review_and_acceptance"),
    ("review_and_acceptance", "closeout"),
}
REQUIRED_FAILURE_ROUTES = {
    ("quality_assurance", "code", "implementation"),
    ("quality_assurance", "design", "architecture_design"),
    ("quality_assurance", "requirement", "idea_intake"),
    ("review_and_acceptance", "change", "change_intake"),
}
REQUIRED_HOOK_EVENTS = {
    "SessionStart",
    "UserPromptSubmit",
    "PreToolUse",
    "PostToolUse",
    "Stop",
}
REQUIRED_SESSION_FIELDS = {
    "project_id",
    "task_id",
    "role",
    "session_id",
    "provider",
    "started_at",
    "last_seen_at",
    "context_state",
    "handoff_inputs",
    "handoff_outputs",
}
REQUIRED_PRISM_ASSISTANCE = {
    "requirements_clarification_review",
    "architecture_review",
    "code_review",
    "test_review",
    "documentation_review",
    "session_loss_recovery",
}
REQUIRED_PRISM_EVIDENCE = {
    "prism_request",
    "provider_reviews",
    "merge_or_resolution",
    "cap_decision",
}


def load_json(path: pathlib.Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def string_set(items: Any, key: str | None = None) -> set[str]:
    result: set[str] = set()
    if not isinstance(items, list):
        return result
    for item in items:
        if key is None:
            if isinstance(item, str) and item.strip():
                result.add(item)
        elif isinstance(item, dict) and isinstance(item.get(key), str) and item[key].strip():
            result.add(item[key])
    return result


def validate_phase(phase: dict[str, Any], failures: list[str]) -> None:
    phase_id = phase.get("id")
    for key in ["id", "role", "name"]:
        if not (isinstance(phase.get(key), str) and phase[key].strip()):
            failures.append(f"{phase_id or '<unknown>'}: {key} 必须是非空字符串")
    for key in ["required_inputs", "required_outputs", "evidence_required"]:
        values = phase.get(key)
        if not isinstance(values, list) or not values or not all(isinstance(item, str) and item.strip() for item in values):
            failures.append(f"{phase_id}: {key} 必须是非空字符串列表")


def validate_execution_runtime(contract: dict[str, Any], failures: list[str]) -> None:
    runtime = contract.get("execution_runtime")
    if not isinstance(runtime, dict):
        failures.append("Loom 工作流缺少 execution_runtime")
        return
    if runtime.get("required_host") != "codex-cli":
        failures.append("Loom 执行宿主必须是 codex-cli，才能承载项目级 Hook")
    if runtime.get("hook_carrier_required") is not True:
        failures.append("Loom 必须声明 Hook 承载为必需能力")
    hooks = set(runtime.get("required_hook_events", []) if isinstance(runtime.get("required_hook_events"), list) else [])
    missing_hooks = sorted(REQUIRED_HOOK_EVENTS - hooks)
    if missing_hooks:
        failures.append(f"Loom Hook 事件要求缺失：{missing_hooks}")
    providers = runtime.get("allowed_role_providers")
    if providers != ["codex-cli"]:
        failures.append("Loom 角色执行方必须限定为 codex-cli，其他 AI 只能作为评审协助方")

    policy = runtime.get("role_session_policy")
    if not isinstance(policy, dict):
        failures.append("Loom 工作流缺少 role_session_policy")
        return
    expected_true = {
        "session_id_required": "Loom 角色必须持久记录 session_id",
        "same_role_must_resume_same_session": "同一角色必须续用同一 session_id",
        "session_loss_alarm_required": "session_id 丢失必须报警",
    }
    for key, message in expected_true.items():
        if policy.get(key) is not True:
            failures.append(message)
    if policy.get("session_scope") != "project_id + task_id + role":
        failures.append("Loom session_id 作用域必须绑定 project_id + task_id + role")
    if policy.get("lost_session_effect") != "mark_role_context_degraded_and_require_assisted_review":
        failures.append("Loom session_id 丢失后必须标记上下文降级并要求协助评审")
    fields = set(policy.get("manifest_required_fields", []) if isinstance(policy.get("manifest_required_fields"), list) else [])
    missing_fields = sorted(REQUIRED_SESSION_FIELDS - fields)
    if missing_fields:
        failures.append(f"Loom 角色会话清单字段缺失：{missing_fields}")


def validate_prism_assistance(contract: dict[str, Any], failures: list[str]) -> None:
    policy = contract.get("prism_assistance_policy")
    if not isinstance(policy, dict):
        failures.append("Loom 工作流缺少 prism_assistance_policy")
        return
    if policy.get("allowed") is not True:
        failures.append("Loom 必须允许角色调用棱镜协助复杂评审")
    required_for = set(policy.get("required_for", []) if isinstance(policy.get("required_for"), list) else [])
    missing_required = sorted(REQUIRED_PRISM_ASSISTANCE - required_for)
    if missing_required:
        failures.append(f"Loom 棱镜协助场景缺失：{missing_required}")
    if policy.get("providers") != ["kimi", "claude-code"]:
        failures.append("Loom 棱镜协助方必须显式限定为 kimi 和 claude-code")
    evidence = set(policy.get("evidence_required", []) if isinstance(policy.get("evidence_required"), list) else [])
    missing_evidence = sorted(REQUIRED_PRISM_EVIDENCE - evidence)
    if missing_evidence:
        failures.append(f"Loom 棱镜协助证据缺失：{missing_evidence}")
    rule = str(policy.get("role_decision_rule") or "")
    if "Cap" not in rule or "blindly" not in rule:
        failures.append("Loom 必须声明 Cap 不能盲从或无理由否决棱镜")


def validate_contract(contract: dict[str, Any]) -> list[str]:
    failures: list[str] = []
    if contract.get("schema_id") != "redcap-loom-workflow-contract":
        failures.append("Loom 工作流合同 schema_id 错误")
    if contract.get("roles_are_phases") is not True:
        failures.append("Loom 工作流必须声明角色是阶段")
    if contract.get("minimum_kernel_completion_allowed") is not False:
        failures.append("Loom 工作流不能允许最小内核替代完整工作流")
    roles = string_set(contract.get("required_roles"))
    missing_roles = sorted(REQUIRED_ROLES - roles)
    if missing_roles:
        failures.append(f"Loom 工作流缺少必需角色：{missing_roles}")
    validate_execution_runtime(contract, failures)
    validate_prism_assistance(contract, failures)
    phases = contract.get("phases")
    if not isinstance(phases, list) or not phases:
        failures.append("Loom 工作流缺少阶段")
        phases = []
    phase_ids = string_set(phases, "id")
    missing_phases = sorted(REQUIRED_PHASES - phase_ids)
    if missing_phases:
        failures.append(f"Loom 工作流缺少必需阶段：{missing_phases}")
    phase_roles = {
        str(phase.get("role"))
        for phase in phases
        if isinstance(phase, dict) and phase.get("role")
    }
    unbound_roles = sorted(REQUIRED_ROLES - phase_roles)
    if unbound_roles:
        failures.append(f"Loom 工作流角色没有绑定阶段：{unbound_roles}")
    for phase in phases:
        if isinstance(phase, dict):
            validate_phase(phase, failures)
        else:
            failures.append("Loom 工作流阶段必须是对象")
    transitions = contract.get("transitions")
    if not isinstance(transitions, list) or not transitions:
        failures.append("Loom 工作流缺少转移")
        transitions = []
    transition_pairs = {
        (str(item.get("from")), str(item.get("to")))
        for item in transitions
        if isinstance(item, dict)
    }
    missing_transitions = sorted(REQUIRED_LINEAR_TRANSITIONS - transition_pairs)
    if missing_transitions:
        failures.append(f"Loom 工作流缺少主线转移：{missing_transitions}")
    for item in transitions:
        if not isinstance(item, dict):
            failures.append("Loom 工作流转移必须是对象")
            continue
        for key in ["from", "to", "trigger"]:
            if not (isinstance(item.get(key), str) and item[key].strip()):
                failures.append(f"转移 {item}: {key} 必须是非空字符串")
        evidence = item.get("evidence")
        if not isinstance(evidence, list) or not evidence or not all(isinstance(value, str) and value.strip() for value in evidence):
            failures.append(f"转移 {item.get('from')}->{item.get('to')} 缺少证据要求")
        if item.get("from") not in phase_ids or item.get("to") not in phase_ids:
            failures.append(f"转移引用未知阶段：{item.get('from')}->{item.get('to')}")
    routes = contract.get("failure_routes")
    if not isinstance(routes, list) or not routes:
        failures.append("Loom 工作流缺少失败回流")
        routes = []
    route_tuples = {
        (str(item.get("from")), str(item.get("root_cause")), str(item.get("to")))
        for item in routes
        if isinstance(item, dict)
    }
    missing_routes = sorted(REQUIRED_FAILURE_ROUTES - route_tuples)
    if missing_routes:
        failures.append(f"Loom 工作流缺少根因回流：{missing_routes}")
    rules = contract.get("completion_rules")
    if not isinstance(rules, dict):
        failures.append("Loom 工作流缺少完成规则")
    else:
        expected = {
            "closeout_requires_all_roles": True,
            "closeout_requires_terminal_acceptance": True,
            "closeout_requires_role_session_manifest": True,
            "closeout_requires_prism_assistance_decisions": True,
            "phase_skipping_allowed": False,
            "report_or_receipt_alone_can_complete": False,
        }
        for key, value in expected.items():
            if rules.get(key) is not value:
                failures.append(f"完成规则 {key} 必须为 {value}")
    return failures


def check(contract_path: pathlib.Path) -> dict[str, Any]:
    contract = load_json(contract_path)
    failures = validate_contract(contract)
    return {
        "schema_id": "redcap-loom-workflow-check",
        "ok": not failures,
        "contract": str(contract_path),
        "roles": sorted(string_set(contract.get("required_roles"))),
        "phases": sorted(string_set(contract.get("phases"), "id")),
        "failures": failures,
    }


def cmd_check(args: argparse.Namespace) -> int:
    result = check(pathlib.Path(args.contract).resolve())
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if result["ok"]:
        print("REDCAP_LOOM_WORKFLOW_OK")
        return 0
    return 1


def cmd_self_check(_: argparse.Namespace) -> int:
    good = load_json(DEFAULT_CONTRACT)
    failures: list[str] = []
    if validate_contract(good):
        failures.append("当前 Loom 工作流合同不应在自检样例中失败")
    missing_role = json.loads(json.dumps(good, ensure_ascii=False))
    missing_role["required_roles"] = [role for role in missing_role["required_roles"] if role != "tester"]
    if not any("必需角色" in item for item in validate_contract(missing_role)):
        failures.append("缺少测试角色的样例没有失败")
    skip_qa = json.loads(json.dumps(good, ensure_ascii=False))
    skip_qa["transitions"] = [
        item for item in skip_qa["transitions"]
        if not (item.get("from") == "implementation" and item.get("to") == "quality_assurance")
    ]
    if not any("主线转移" in item for item in validate_contract(skip_qa)):
        failures.append("跳过测试阶段的样例没有失败")
    bad_completion = json.loads(json.dumps(good, ensure_ascii=False))
    bad_completion["completion_rules"]["report_or_receipt_alone_can_complete"] = True
    if not any("report_or_receipt" in item for item in validate_contract(bad_completion)):
        failures.append("报告或回执单独完成的样例没有失败")
    missing_session = json.loads(json.dumps(good, ensure_ascii=False))
    missing_session["execution_runtime"]["role_session_policy"].pop("session_id_required", None)
    if not any("session_id" in item for item in validate_contract(missing_session)):
        failures.append("缺少角色 session_id 要求的样例没有失败")
    missing_alarm = json.loads(json.dumps(good, ensure_ascii=False))
    missing_alarm["execution_runtime"]["role_session_policy"]["session_loss_alarm_required"] = False
    if not any("丢失" in item or "报警" in item for item in validate_contract(missing_alarm)):
        failures.append("缺少 session 丢失报警的样例没有失败")
    missing_prism = json.loads(json.dumps(good, ensure_ascii=False))
    missing_prism["prism_assistance_policy"]["required_for"] = ["code_review"]
    if not any("棱镜协助场景缺失" in item for item in validate_contract(missing_prism)):
        failures.append("缺少棱镜协助场景的样例没有失败")
    print(json.dumps({"ok": not failures, "failures": failures}, ensure_ascii=False, indent=2))
    if failures:
        return 1
    print("REDCAP_LOOM_WORKFLOW_SELF_CHECK_OK")
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="RedCap Loom 角色化工程工作流检查器")
    sub = parser.add_subparsers(dest="command", required=True)
    check_cmd = sub.add_parser("check")
    check_cmd.add_argument("--contract", default=str(DEFAULT_CONTRACT))
    check_cmd.set_defaults(func=cmd_check)
    self_check = sub.add_parser("self-check")
    self_check.set_defaults(func=cmd_self_check)
    return parser


def main() -> int:
    parser = build_parser()
    args = parser.parse_args()
    return int(args.func(args))


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""RedCap 自我净化与 Cap 私有人格沉淀边界检查器。"""

from __future__ import annotations

import argparse
import json
import pathlib
import sys
import tempfile
from typing import Any


REPO_ROOT = pathlib.Path(__file__).resolve().parents[2]
DEFAULT_CONTRACT = REPO_ROOT / "assets" / "contracts" / "self-purification.json"

REQUIRED_RETRIEVAL_SCOPES = {"implementation", "completion", "e2e", "self-development"}
REQUIRED_RESULT_HANDLING = {"use_relevant_entry", "record_no_relevant_entry", "record_skip_reason"}
REQUIRED_TRIGGERS = {
    "user_correction",
    "prism_block_or_concern",
    "e2e_failure",
    "hook_false_positive",
    "workflow_drift",
    "completion_claim_correction",
    "new_reusable_design",
    "persona_signal",
}
REQUIRED_CANDIDATE_FIELDS = {
    "id",
    "source_task",
    "trigger",
    "lesson",
    "privacy_class",
    "proposed_destination",
    "evidence",
    "created_at",
}
REQUIRED_DECISIONS = {"promote_public", "keep_private", "no_promote", "defer_with_owner"}
REQUIRED_PROMOTION = {
    "reviewed_source",
    "privacy_checked",
    "deduplicated",
    "human_readable",
    "index_first",
    "source_refs_exist",
}
FORBIDDEN_PUBLIC_DESTINATIONS = {
    "assets/knowledge/entries",
    "assets/knowledge/arsenal",
    "assets/contracts",
    "assets/docs",
}
REQUIRED_PERSONA_EVIDENCE_FIELDS = {"candidate_id", "decision", "source_task", "reason", "hash", "counts"}
FORBIDDEN_PERSONA_EVIDENCE = {"private_identity_body", "raw_persona_body", "secret", "token", "credential"}
REQUIRED_BEFORE = {"knowledge_retrieval_or_skip_reason"}
REQUIRED_AFTER = {"harvest_candidate_or_no_candidate_reason", "review_decision", "promotion_or_no_promote_result"}


def load_json(path: pathlib.Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise SystemExit(f"无法读取 JSON：{path}: {exc}") from exc
    if not isinstance(payload, dict):
        raise SystemExit(f"JSON 必须是对象：{path}")
    return payload


def as_set(payload: dict[str, Any], key: str) -> set[str]:
    value = payload.get(key)
    if not isinstance(value, list):
        return set()
    return {str(item) for item in value if isinstance(item, str) and item.strip()}


def missing(required: set[str], actual: set[str]) -> list[str]:
    return sorted(required - actual)


def validate_contract(contract: dict[str, Any]) -> list[str]:
    failures: list[str] = []
    if contract.get("schema_id") != "redcap-self-purification-contract":
        failures.append("自我净化合同 schema_id 错误")
    if contract.get("status") != "runtime-gated":
        failures.append("自我净化合同必须声明 runtime-gated")

    retrieval = contract.get("pre_task_retrieval")
    if not isinstance(retrieval, dict):
        failures.append("自我净化缺少 pre_task_retrieval")
    else:
        missing_scopes = missing(REQUIRED_RETRIEVAL_SCOPES, as_set(retrieval, "required_for"))
        if missing_scopes:
            failures.append(f"任务前知识检索覆盖范围缺失：{missing_scopes}")
        if retrieval.get("command") != "runtime/bin/redcap knowledge-gateway search <query>":
            failures.append("任务前知识检索必须使用 knowledge-gateway search")
        if retrieval.get("evidence_field") != "knowledge_retrieval_evidence":
            failures.append("任务前知识检索必须写入 knowledge_retrieval_evidence")
        if retrieval.get("skip_requires_reason") is not True:
            failures.append("跳过任务前知识检索必须写明理由")
        missing_handling = missing(REQUIRED_RESULT_HANDLING, as_set(retrieval, "minimum_result_handling"))
        if missing_handling:
            failures.append(f"任务前知识检索结果处理缺失：{missing_handling}")

    harvest = contract.get("post_task_harvest")
    if not isinstance(harvest, dict):
        failures.append("自我净化缺少 post_task_harvest")
    else:
        missing_triggers = missing(REQUIRED_TRIGGERS, as_set(harvest, "required_triggers"))
        if missing_triggers:
            failures.append(f"任务后候选触发器缺失：{missing_triggers}")
        missing_fields = missing(REQUIRED_CANDIDATE_FIELDS, as_set(harvest, "candidate_required_fields"))
        if missing_fields:
            failures.append(f"任务后候选字段缺失：{missing_fields}")
        missing_decisions = missing(REQUIRED_DECISIONS, as_set(harvest, "decision_labels"))
        if missing_decisions:
            failures.append(f"任务后评审决策缺失：{missing_decisions}")
        if harvest.get("no_promote_requires_reason") is not True:
            failures.append("no-promote 必须写明理由")

    public_path = contract.get("public_knowledge_path")
    if not isinstance(public_path, dict):
        failures.append("自我净化缺少 public_knowledge_path")
    else:
        if public_path.get("gateway") != "runtime/bin/redcap knowledge-gateway":
            failures.append("公共知识路径必须经过 knowledge-gateway")
        if public_path.get("forge") != "runtime/bin/redcap forge check":
            failures.append("公共知识路径必须经过 Forge 检查")
        if public_path.get("arsenal") != "runtime/bin/redcap arsenal check":
            failures.append("公共知识路径必须经过 arsenal 检查")
        missing_promotion = missing(REQUIRED_PROMOTION, as_set(public_path, "promotion_requires"))
        if missing_promotion:
            failures.append(f"公共知识晋升条件缺失：{missing_promotion}")

    persona = contract.get("cap_persona_distillation")
    if not isinstance(persona, dict):
        failures.append("自我净化缺少 cap_persona_distillation")
    else:
        if persona.get("enabled") is not True:
            failures.append("Cap 人格沉淀必须显式启用")
        if persona.get("privacy_class") != "cap-private":
            failures.append("Cap 人格沉淀必须标记为 cap-private")
        if persona.get("public_write_forbidden") is not True:
            failures.append("Cap 人格沉淀禁止写入公共知识库")
        forbidden = as_set(persona, "public_destinations_forbidden")
        missing_forbidden = missing(FORBIDDEN_PUBLIC_DESTINATIONS, forbidden)
        if missing_forbidden:
            failures.append(f"Cap 私有人格公共禁写目录缺失：{missing_forbidden}")
        if persona.get("private_identity_source") != "/Users/norven/.cap/identity.md":
            failures.append("Cap 私有人格必须绑定私有身份源")
        missing_evidence_fields = missing(REQUIRED_PERSONA_EVIDENCE_FIELDS, as_set(persona, "evidence_may_contain"))
        if missing_evidence_fields:
            failures.append(f"Cap 人格证据允许字段缺失：{missing_evidence_fields}")
        missing_forbidden_evidence = missing(FORBIDDEN_PERSONA_EVIDENCE, as_set(persona, "evidence_must_not_contain"))
        if missing_forbidden_evidence:
            failures.append(f"Cap 人格证据禁含字段缺失：{missing_forbidden_evidence}")
        if persona.get("identity_mutation_requires_human") is not True:
            failures.append("修改 Cap 身份必须要求人工授权")

    binding = contract.get("lifecycle_binding")
    if not isinstance(binding, dict):
        failures.append("自我净化缺少 lifecycle_binding")
    else:
        missing_before = missing(REQUIRED_BEFORE, as_set(binding, "required_before_implementation"))
        if missing_before:
            failures.append(f"生命周期实施前绑定缺失：{missing_before}")
        missing_after = missing(REQUIRED_AFTER, as_set(binding, "required_after_task"))
        if missing_after:
            failures.append(f"生命周期任务后绑定缺失：{missing_after}")
        e2e_binding = str(binding.get("e2e_failure_binding") or "")
        if "E2E" not in e2e_binding or "candidate" not in e2e_binding:
            failures.append("E2E 失败必须绑定候选抽取或无候选理由")
    return failures


def check(path: pathlib.Path = DEFAULT_CONTRACT) -> dict[str, Any]:
    contract = load_json(path)
    failures = validate_contract(contract)
    return {
        "schema_id": "redcap-self-purification-check",
        "ok": not failures,
        "contract": str(path),
        "failures": failures,
    }


def cmd_check(args: argparse.Namespace) -> int:
    result = check(pathlib.Path(args.contract).resolve())
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if result["ok"]:
        print("REDCAP_SELF_PURIFICATION_OK")
        return 0
    return 1


def cmd_self_check(_: argparse.Namespace) -> int:
    failures: list[str] = []
    good = load_json(DEFAULT_CONTRACT)
    good_failures = validate_contract(good)
    if good_failures:
        failures.append(f"当前自我净化合同不应失败：{good_failures}")
    missing_retrieval = json.loads(json.dumps(good, ensure_ascii=False))
    missing_retrieval["pre_task_retrieval"]["required_for"] = ["implementation"]
    if not any("任务前知识检索覆盖范围缺失" in item for item in validate_contract(missing_retrieval)):
        failures.append("缺少任务前检索覆盖范围的样例没有失败")
    public_persona = json.loads(json.dumps(good, ensure_ascii=False))
    public_persona["cap_persona_distillation"]["public_write_forbidden"] = False
    if not any("公共知识库" in item for item in validate_contract(public_persona)):
        failures.append("允许 Cap 人格写入公共知识库的样例没有失败")
    no_no_promote_reason = json.loads(json.dumps(good, ensure_ascii=False))
    no_no_promote_reason["post_task_harvest"]["no_promote_requires_reason"] = False
    if not any("no-promote" in item for item in validate_contract(no_no_promote_reason)):
        failures.append("no-promote 无理由样例没有失败")
    with tempfile.TemporaryDirectory(prefix="redcap-self-purification-") as raw:
        tmp = pathlib.Path(raw)
        fixture = tmp / "contract.json"
        fixture.write_text(json.dumps(good, ensure_ascii=False), encoding="utf-8")
        if not check(fixture)["ok"]:
            failures.append("临时合同路径检查失败")
    print(json.dumps({"ok": not failures, "failures": failures}, ensure_ascii=False, indent=2))
    if failures:
        return 1
    print("REDCAP_SELF_PURIFICATION_SELF_CHECK_OK")
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="RedCap 自我净化与 Cap 私有人格边界检查器")
    sub = parser.add_subparsers(dest="command", required=True)
    check_cmd = sub.add_parser("check")
    check_cmd.add_argument("--contract", default=str(DEFAULT_CONTRACT))
    check_cmd.set_defaults(func=cmd_check)
    sub.add_parser("self-check").set_defaults(func=cmd_self_check)
    return parser


def main() -> int:
    parser = build_parser()
    args = parser.parse_args()
    return int(args.func(args))


if __name__ == "__main__":
    sys.exit(main())

